"""GDB, Git, visual diagnostics, split panes and independent zoom on a real device."""
import json,pathlib,sys,time
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parents[1]/'tools'))
from device_cdp import Device
ROOT=pathlib.Path(__file__).resolve().parents[1]
d=Device();results=[]
def test(name,code,check=lambda x:bool(x)):
    start=time.monotonic()
    try:
        value=d.evaluate(code);assert check(value),str(value)[:4000]
        results.append({'test':name,'passed':True,'seconds':round(time.monotonic()-start,2),'evidence':value});print('PASS',name,flush=True);return value
    except Exception as e:results.append({'test':name,'passed':False,'error':str(e)});print('FAIL',name,str(e)[:1500],flush=True)
name='tools-verify-'+str(int(time.time()))
try:
    test('GDB and Git versions',"native('probe')",lambda r:'18.1' in r['gdb'] and 'git version' in r['git'])
    setup="""(async()=>{window.toolTest={original:forge.state.project,events:[]};onNative('output',e=>toolTest.events.push(e));window.until=async(fn,timeout=20000)=>{const start=Date.now();while(Date.now()-start<timeout){const r=fn();if(r)return r;await new Promise(r=>setTimeout(r,80));}throw new Error('Condition timeout');};await native('newProject',{name:NAME,language:'c'});await forge.switchProject(NAME);return forge.state.root;})()""".replace('NAME',json.dumps(name))
    test('Isolated tools project',setup)
    code='#include <stdio.h>\nint main(void) {\n    int value = 5;\n    value += 2;\n    printf("%d\\n", value);\n    return 0;\n}\n'
    test('Debug build with source symbols',"(async()=>{const model=forge.active.model;model.setValue("+json.dumps(code)+");await forge.saveAll();toolTest.debugBuild=await native('build',{path:forge.active.path,options:{...forge.settings,optimization:'debug'},mode:'file',id:'tools-debug-build'});return toolTest.debugBuild;})()",lambda r:r['code']==0)
    test('GDB starts and stops at main',"(async()=>{const path=forge.active.path;forge.debugger.breakpoints.set(path,new Map([[4,null]]));await forge.debugger.start(toolTest.debugBuild.executable);await until(()=>forge.debugger.paused&&forge.debugger.frames?.length);return{frames:forge.debugger.frames,status:document.querySelector('#debugStatus').textContent};})()",lambda r:any(f['func']=='main' for f in r['frames']))
    test('Breakpoint and value inspection',"(async()=>{const serial=forge.debugger.stopSerial;await forge.debugger.command('-exec-continue');await until(()=>forge.debugger.paused&&forge.debugger.stopSerial>serial);const value=await forge.debugger.command('-data-evaluate-expression value');return{value:value.value,frames:forge.debugger.frames};})()",lambda r:r['value']=='5')
    test('Step over changes a local variable',"(async()=>{const serial=forge.debugger.stopSerial;await forge.debugger.command('-exec-next');await until(()=>forge.debugger.paused&&forge.debugger.stopSerial>serial);const value=await forge.debugger.command('-data-evaluate-expression value');await until(()=>document.querySelector('#debugVariables').textContent.includes('7'));return{value:value.value,ui:document.querySelector('#debugVariables').textContent,frame:forge.debugger.frames[0]};})()",lambda r:r['value']=='7' and '7' in r['ui'])
    test('Watch expressions use real inferior state',"(async()=>{await forge.debugger.addWatch('value * 3');return document.querySelector('#debugWatches').textContent;})()",lambda r:'21' in r)
    test('Debugger resumes and captures PTY output',"(async()=>{await forge.debugger.command('-exec-continue');await until(()=>!forge.debugger.active);return toolTest.events.filter(e=>e.id.startsWith('debug-')).map(e=>e.text).join('');})()",lambda r:'7' in r)
    test('Git init and commit',"(async()=>{const init=await native('git',{action:'init'});const commit=await native('git',{action:'commit',name:'IDE Acceptance',email:'acceptance@example.invalid',message:'Initial test project',stageAll:true});return{init,commit,status:await native('git',{action:'status'})};})()",lambda r:r['init']['code']==0 and r['commit']['code']==0 and r['status']['text']=='')
    test('Git diff compares HEAD and working copy',"(async()=>{forge.active.model.setValue(forge.active.model.getValue()+'// changed in working copy\n');await forge.saveAll();const diff=await native('git',{action:'diff',path:forge.active.path});return{diff,status:await native('git',{action:'status'}),log:await native('git',{action:'log'})};})()".replace("copy\n'","copy\\n'"),lambda r:'changed in working copy' in r['diff']['modified'] and 'changed in working copy' not in r['diff']['original'] and 'main.c' in r['status']['text'] and 'Initial test project' in r['log']['text'])
    test('Git branch creation and UI',"(async()=>{const branch=await native('git',{action:'newBranch',branch:'test-branch'});await forge.showGit();return{branch,ui:document.querySelector('#gitSide').innerText};})()",lambda r:r['branch']['code']==0 and 'test-branch' in r['ui'])
    test('Independent code and UI scales',"(async()=>{forge.setUIScale(125);forge.setCodeScale(150);await new Promise(r=>setTimeout(r,200));return{ui:forge.settings.uiScale,code:forge.settings.codeScale,font:forge.editor.getOption(monaco.editor.EditorOption.fontSize),topbar:getComputedStyle(document.querySelector('.topbar')).height};})()",lambda r:r['ui']==125 and r['code']==150 and abs(r['font']-21)<.1)
    test('Two resizable editor panes',"(async()=>{forge.splitEditor('side');forge.settings.layout.splitRatio=.37;forge.layoutEditors();await new Promise(r=>setTimeout(r,150));const a=document.querySelector('#editor').getBoundingClientRect(),b=document.querySelector('#secondaryEditor').getBoundingClientRect();const result={first:a.width,second:b.width,sameModel:forge.primaryEditor.getModel()===forge.secondaryEditor.getModel()};forge.splitEditor('stacked');return{...result,stacked:document.querySelector('#editorArea').classList.contains('split-stacked')};})()",lambda r:r['first']>0 and r['second']>r['first'] and r['sameModel'] and r['stacked'])
    test('Reset layout and zoom',"(async()=>{forge.resetLayout();forge.setUIScale(100);forge.setCodeScale(100);return{split:!!forge.secondaryEditor,scale:forge.settings.uiScale,code:forge.settings.codeScale};})()",lambda r:not r['split'] and r['scale']==100 and r['code']==100)
    unused='static int unused_function(int unused_parameter) { return 10; }\nclass Example { int unused_field = 0; public: int get() const { return 42; } };\nint main() { int unused_variable = 5; Example object; return object.get() == 42 ? 0 : 1; }\n'
    test('Unused functions, parameters, fields and variables have gray decorations',"(async()=>{const path=forge.state.root+'/unused.cpp';await native('newFile',{path,text:"+json.dumps(unused)+"});await forge.refreshTree();await forge.openFile(path);await forge.lsp.start();const model=forge.active.model,uri=model.uri.toString();await until(()=>{const p=forge.diagnosticMap.get(uri);return p?.diagnostics.some(x=>x.message.includes('unused_variable'));});await new Promise(r=>setTimeout(r,150));const diagnostics=forge.diagnosticMap.get(uri).diagnostics;const decorations=model.getAllDecorations().filter(d=>d.options.inlineClassName==='forge-unused-symbol');return{diagnostics,decorations:decorations.map(d=>({range:d.range,text:model.getValueInRange(d.range)})),colors:[...document.querySelectorAll('.forge-unused-symbol')].map(e=>getComputedStyle(e).color)};})()",lambda r:all(any(name in e['message'] for e in r['diagnostics']) for name in ['unused_function','unused_parameter','unused_field','unused_variable']) and len(r['decorations'])>=4 and 'rgb(111, 115, 122)' in r['colors'])
finally:
    try:d.evaluate("(async()=>{if(forge.debugger.active)await forge.debugger.stop();forge.resetLayout();forge.setUIScale(100);forge.setCodeScale(100);await forge.switchProject(toolTest.original);return true;})()")
    except Exception:pass
    report={'device':'realme RMX3951','android':'16','testProject':name,'results':results,'passed':sum(r['passed'] for r in results),'total':len(results)}
    (ROOT/'verification-tools.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    print(json.dumps({'passed':report['passed'],'total':report['total']}),flush=True);d.close()
